      350:    _sel_b1 = (v16u8) __msa_pckev_b((v16i8) _sel_h1, (v16i8) _sel_h1);         \
      351:    inp4 = (v16u8) __msa_bmnz_v(inp4, inp5, _sel_b1);                          \
      352:    out0 += inp4;                                                              \
      353: }
